export function graphPropertyNames(folder: string, odataType: unknown): Set<string> {
  const result = new Set<string>()
  const root = Object.hasOwn(roots, folder) ? roots[folder] : undefined
  if (!root) return result
  const subtype = typeof odataType === 'string' ? /^#microsoft\.graph\.(\w+)$/.exec(odataType)?.[1] : undefined
  const chain = (start: string): string[] => {
    const names: string[] = []
    for (let name = start; name && Object.hasOwn(schema, name); name = schema[name]![0]) names.push(name)
    return names
  }
  const candidate = subtype ? chain(subtype) : []
  for (const name of candidate.includes(root) ? candidate : chain(root)) {
    for (const property of schema[name]![1].split(' ')) if (property) result.add(property)
  }
  return result
}

/** Persisted records need only the field name. The writer checks the concrete type. */
const knownNames = new Set(Object.values(schema).flatMap(([, properties]) => properties.split(' ').filter(Boolean)))

export function isGraphPropertyName(value: string): boolean {
  return knownNames.has(value)
}
